fn is_sorted(a: &[i32]) -> bool {
    // Iterate over each consecutive pair in the slice
    // If any earlier element is greater than its successor, it's not sorted.
    for window in a.windows(2) {
        if window[0] > window[1] {
            return false;
        }
    }
    // If we never find an inversion, the slice is sorted in nondecreasing order.
    true
}

